"""The VJ's shaders and imports: Shadertoy shaders' channels and passes, MilkDrop presets' shapes and custom waves,
MilkDrop 2's shaders translated, a project's Python looks run only once allowed, and the phone's VJ commands. The
shaders' runs are left out where there is no OpenGL 3.3 (moderngl)."""
# AI: below section was generated by an AI
import os
import sys
import tempfile

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np

from native import milk, milk_md2, phone, vj_glsl, vj_looks

fails = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        fails.append(what)


# --- a shader's passes and channels, read --------------------------------------------------------------
one = "void mainImage(out vec4 c, in vec2 p) { c = vec4(1.0); }"
ps = vj_glsl.passes(one)
check(len(ps) == 1 and ps[0][0] == "image" and [ps[0][2][k] for k in range(4)] == list(vj_glsl.DEFAULT_CHANNELS),
      "one pass: the image, the channels the defaults")
multi = """//@ iChannel3 = picture
//@ common
float half_(float x) { return x * 0.5; }
//@ buffer B
//@ iChannel0 = B
void mainImage(out vec4 c, in vec2 p) { c = texture(iChannel0, p / iResolution.xy) + vec4(half_(0.2), 0.0, 0.0, 0.0); }
//@ buffer A
void mainImage(out vec4 c, in vec2 p) { c = vec4(0.0, 0.25, 0.0, 1.0); }
//@ image
//@ iChannel0 = A
//@ iChannel1 = B
void mainImage(out vec4 c, in vec2 p) { vec2 uv = p / iResolution.xy;
    c = vec4(texture(iChannel1, uv).r, texture(iChannel0, uv).g, texture(iChannel3, uv).b, 1.0); }
"""
ps = vj_glsl.passes(multi)
check([p[0] for p in ps] == ["A", "B", "image"], "passes in Shadertoy's order: A, B, then the image")
check(ps[1][2][0] == "B" and ps[2][2][0] == "A" and ps[2][2][1] == "B" and ps[2][2][3] == "picture" and
      ps[0][2][2] == "noise", "each pass its channels: its own, those before the passes, the defaults")
check(all("half_" in p[1] for p in ps), "Common before every pass")
check(vj_glsl.channels_of(multi) == ["A", "B", "noise", "picture"], "the image's channels for the deck's row")
for bad, what in (("//@ iChannel0 = banana\n" + one, "a channel that is none"),
                  ("//@ buffer A\n" + one, "passes and no image")):
    try:
        vj_glsl.passes(bad)
        check(False, what + ": said")
    except ValueError as e:
        check(True, f"{what}: said ({e})")

# --- MilkDrop 2's shaders, translated ----------------------------------------------------------------
hlsl = """float3 tint = 0.5;
sampler sampler_pw_noise_lq;
static const float k = 2;
shader_body
{
    float2 d = uv - 0.5;
    ret = 0;
    ret = lerp(GetPixel(uv), GetBlur2(uv), saturate(length(d) * k));
    ret *= tint * frac(time) + tex3D(sampler_noisevol_hq, float3(uv, time)).x;
}"""
src = milk_md2.translate(hlsl, "comp")
check("vec3 tint = vec3(0.5);" in src and "ret = vec3(0);" in src and "const float k = 2;" in src and
      "sampler sampler_pw" not in src, "HLSL's ways made GLSL's: a number for a vector, static const, samplers")
try:
    milk_md2.translate("float3 x = 1;", "warp")
    check(False, "no shader_body: said")
except ValueError:
    check(True, "no shader_body: said")
fb = np.zeros((8, 8, 3), np.float32)
check(milk_md2.blurs(fb, src)[1] is not fb and milk_md2.blurs(fb, milk_md2.translate("shader_body { ret = 1; }", "comp"))[0] is fb,
      "the blurs made only for a shader that reads one")

# --- a preset with shapes and a custom wave ----------------------------------------------------------
PRESET = """[preset00]
fDecay=0.9
fWaveAlpha=0
shapecode_0_enabled=1
shapecode_0_sides=4
shapecode_0_num_inst=2
shapecode_0_rad=0.2
shapecode_0_r=1
shapecode_0_g=0
shapecode_0_b=0
shapecode_0_a=1
shapecode_0_r2=1
shapecode_0_g2=0
shapecode_0_b2=0
shapecode_0_a2=1
shapecode_0_border_a=0
shape_0_init1=t1 = 0.3;
shape_0_per_frame1=x = 0.5 + if(equal(instance, 0), -t1, t1); y = 0.5;
shapecode_1_enabled=0
wavecode_0_enabled=1
wavecode_0_samples=64
wavecode_0_bUseDots=1
wavecode_0_r=0
wavecode_0_g=0
wavecode_0_b=1
wave_0_per_point1=x = sample; y = 0.9;
"""
pre = milk.parse(PRESET, "shapes")
check(len(pre["shapes"]) == 1 and len(pre["waves"]) == 1 and pre["shapes"][0]["p"]["num_inst"] == 2,
      "enabled shapes and waves read, a disabled one left out")


class C:
    pass


def ctx(w=64, h=48):
    c = C()
    c.w, c.h = w, h
    c.u, c.v = np.meshgrid(np.linspace(0, 1, w, dtype=np.float32), np.linspace(0, 1, h, dtype=np.float32))
    c.x, c.y = (c.u - 0.5) * 2 * w / h, (c.v - 0.5) * 2
    c.r, c.a = np.hypot(c.x, c.y), np.arctan2(c.y, c.x)
    c.amount, c.speed, c.video, c.bands = 0.5, 1.0, None, None
    c.t, c.dt, c.beat, c.bass, c.mid, c.treb, c.level = 0.0, 1 / 30, 0.0, 0.3, 0.3, 0.3, 0.5
    c.wave = np.zeros(64, np.float32)
    return c


c = ctx()
st = {}
out = milk.look_draw(pre)(c, st)
left, right = out[24, int(0.2 * 63)], out[24, int(0.8 * 63)]
check(left[0] > 0.9 and right[0] > 0.9 and out[24, 32, 0] < 0.2, f"two instances of a red square, either side ({left}, {right})")
check(out[int(0.1 * 47), 10, 2] > 0.5, "the custom wave's blue dots along the top")

# --- run on the graphics card ---------------------------------------------------------------------------
ok, why = vj_glsl.available()
if ok:
    uni = {"iResolution": (16.0, 12.0, 1.0), "iTime": 0.0}
    pic = os.path.join(tempfile.mkdtemp(), "p.png")
    from PIL import Image
    Image.new("RGB", (4, 4), (0, 0, 255)).save(pic)
    for _ in range(3):
        img, err = vj_glsl.render("multi", multi, 16, 12, uni, None, None, wait=True, picture=pic)
    check(not err and abs(img[6, 8, 0] - 0.3) < 0.02 and abs(img[6, 8, 1] - 0.25) < 0.02 and img[6, 8, 2] > 0.95,
          f"passes run: B adds a tenth a frame (three: 0.3), A's green, the picture's blue ({err} {img[6, 8] if img is not None else None})")
    img, err = vj_glsl.render("multi2", multi, 16, 12, uni, None, None, wait=True, picture=pic, channels=["", "", "", "none"])
    check(img is not None and img[6, 8, 2] < 0.05, "a deck's choice over the file's: iChannel3 nothing")
    MD2 = PRESET.replace("fWaveAlpha=0", "fWaveAlpha=0\nwarp_1=`shader_body\nwarp_2=`{ ret = tex2D(sampler_main, uv).xyz * 0.5; }\n"
                         "comp_1=`shader_body\ncomp_2=`{ ret = float3(0, 1, 0) * (1 - GetPixel(uv).x); }")
    pre2 = milk.parse(MD2, "md2")
    st2 = {}
    out2 = milk.look_draw(pre2)(ctx(), st2)
    check(not st2.get("warn") and out2[24, 32, 1] > 0.9 and out2[24, int(0.2 * 63), 1] < 0.1,
          f"MilkDrop 2's composite shader shows the frame its way (green where there is no square) {st2.get('warn')}")
    bad = PRESET + "comp_1=`shader_body\ncomp_2=`{ ret = nope; }\n"
    st3 = {}
    out3 = milk.look_draw(milk.parse(bad, "bad"))(ctx(), st3)
    check("comp shader left out" in st3.get("warn", "") and out3[24, int(0.2 * 63), 0] > 0.9,
          "a shader that will not compile: the preset runs without it, and says so")
else:
    print("skip the runs: " + why)


# --- a project's Python looks: run only once allowed -----------------------------------------------------
class Proj:
    path = tempfile.mkdtemp()


d = vj_looks.user_dir(Proj)
os.makedirs(d, exist_ok=True)
open(os.path.join(d, "mine.py"), "w").write("NAME = 'Mine Test'\ndef draw(c, st):\n    return c.u[..., None].repeat(3, 2)\n")
errs = vj_looks.load_user(Proj, allow_py=False)
check("Mine Test" not in vj_looks.LOOKS and errs == [("mine.py", vj_looks.NOT_ALLOWED)], "not allowed: not run, said")
errs = vj_looks.load_user(Proj, allow_py=True)
check("Mine Test" in vj_looks.LOOKS and not errs, "allowed: run and listed")
errs = vj_looks.load_user(Proj, allow_py=False)
check("Mine Test" not in vj_looks.LOOKS, "no longer allowed: unlisted")
os.remove(os.path.join(d, "mine.py"))
vj_looks.load_user(Proj)

# --- the phone's VJ commands -----------------------------------------------------------------------
check(phone.check({"a": "vjlevel", "d": 2, "v": 0.5}) == {"a": "vjlevel", "d": 2, "v": 0.5}, "a deck's level")
check(phone.check({"a": "vjlook", "d": 1, "v": "Plasma"}) == {"a": "vjlook", "d": 1, "v": "Plasma"}, "a deck's look")
check(phone.check({"a": "vjlevel", "d": 5, "v": 0.5}) is None and phone.check({"a": "vjlook", "d": 0, "v": ""}) is None,
      "a deck that is not, a look that is nothing: refused")

print("FAILED:", fails if fails else "none")
sys.exit(1 if fails else 0)
# AI: end
